81	void PrinterMenu::show_root(const Ptr& self)
82	{
83	    auto* menu = self->m_menu.get();
84	    if (menu == nullptr) return; // the popup went away; nothing to rebuild
85	    const auto printer    = SetupCommands::current_printer();
86	    const auto connection = SetupCommands::printer_connection();
87	    const auto plates     = SetupCommands::bed_types();
88	
89	    std::vector<HeaderMenuItem> rows;
90	
91	    // Row 1: the machine and what it is doing. A state JusPrin cannot observe
92	    // reads as "Not connected" with a plain consequence, never as a guess and
93	    // never in a warning colour -- the chip makes no claim about the machine.
94	    HeaderMenuItem machine;
95	    machine.label           = printer.nickname.empty() ? _L("No printer selected") : printer.nickname;
96	    machine.decoration.bold = true;
97	    machine.enabled         = connection.monitor_available && !printer.from_file;
98	    if (printer.from_file) {
99	        // Not one of the person's printers, so there is no machine to report
100	        // on: the row says where the profile came from instead.
101	        machine.decoration.sub_label      = _L("From the file · not one of your printers");
102	        machine.decoration.sub_label_tone = StatusTone::Warning;
103	        machine.decoration.sub_label_role = TextRole::BodySmall;
104	    } else
105	    switch (connection.state) {
106	    case SetupCommands::ConnectionState::Ready:
107	        machine.decoration.status      = StatusTone::Positive;
108	        machine.decoration.status_word = _L("Ready");
109	        machine.decoration.trailing    = HeaderIcon::Monitor;
110	        break;
111	    case SetupCommands::ConnectionState::Printing:
112	        machine.decoration.status      = StatusTone::Busy;
113	        machine.decoration.status_word = _L("Printing");
114	        machine.decoration.trailing    = HeaderIcon::Monitor;
115	        break;
116	    case SetupCommands::ConnectionState::Paused:
117	        machine.decoration.status      = StatusTone::Warning;
118	        machine.decoration.status_word = _L("Paused");
119	        machine.decoration.trailing    = HeaderIcon::Monitor;
120	        break;
121	    case SetupCommands::ConnectionState::Connected:
122	        // Answers, and does not say what it is doing: no claim either way.
123	        machine.decoration.status      = StatusTone::Neutral;
124	        machine.decoration.status_word = _L("Connected");
125	        machine.decoration.trailing    = HeaderIcon::Monitor;
126	        break;
127	    case SetupCommands::ConnectionState::Offline:
128	        machine.decoration.status      = StatusTone::Neutral;
129	        machine.decoration.status_word = _L("Offline");
130	        machine.decoration.trailing    = HeaderIcon::Monitor;
131	        break;
132	    case SetupCommands::ConnectionState::Checking:
133	        // A print host not read lately: its window can open meanwhile, and
134	        // says so itself when the page does not load.
135	        machine.decoration.status      = StatusTone::Neutral;
136	        machine.decoration.status_word = _L("Checking connection") + wxString::FromUTF8("\xE2\x80\xA6");
137	        machine.decoration.trailing    = HeaderIcon::Monitor;
138	        break;
139	    case SetupCommands::ConnectionState::NotConnected:
140	        machine.decoration.status      = StatusTone::Neutral;
141	        machine.decoration.status_word = _L("Not connected");
142	        // Connect… is deferred to a later slice, so the sub-line states the
143	        // consequence rather than offering an action that would do nothing.
144	        machine.decoration.sub_label       = _L("Prints go to a card.");
145	        machine.decoration.sub_label_role  = TextRole::Label;
146	        machine.decoration.sub_label_faint = true;
147	        break;
148	    }
149	    if (!connection.print_host_printer.empty() && !printer.from_file)
150	        machine.invoke = [name = connection.print_host_printer] {
151	            // The same window as the printer's card on Home: the host's own page.
152	            if (ShellController* shell = installed_shell())
153	                shell->home_view()->backend().open_printer_window(name);
154	        };
155	    else if (connection.monitor_available && !printer.from_file)
156	        machine.invoke = [] {
157	            // The same window as the printer's card on Home.
158	            const std::string device = SetupCommands::monitored_device();
159	            if (ShellController* shell = installed_shell(); shell != nullptr && !device.empty())
160	                shell->home_view()->backend().open_monitor_window(device);
161	        };
162	    rows.push_back(std::move(machine));
163	    rows.push_back(separator());
164	
165	    // Read-only: a printer's nozzle is fixed by its parent system profile, and
166	    // changing it here would mean moving the printer to another parent and
167	    // deciding which of its own settings follow. Prepare only shows it.
168	    HeaderMenuItem nozzle;
169	    nozzle.label             = _L("Nozzle");
170	    nozzle.decoration.detail = nozzle_text(printer.nozzle);
171	    nozzle.enabled           = false;
172	    rows.push_back(std::move(nozzle));
173	
174	    HeaderMenuItem plate;
175	    plate.label = _L("Plate");
176	    for (const auto& choice : plates)
177	        if (choice.current) plate.decoration.detail = choice.label;
178	    plate.enabled = !plates.empty();
179	    if (plate.enabled) {
180	        plate.decoration.trailing = HeaderIcon::Right;
181	        plate.keeps_open          = true;
182	        plate.invoke              = [self] { show_plates(self); };
183	    }
184	    rows.push_back(std::move(plate));
185	    rows.push_back(separator());
186	
187	    // Home already resolves each saved printer's device or print-host state.
188	    // Use that same reading here so an unselected printer does not silently
189	    // become "Idle" just because its profile exists.
190	    const auto saved = installed_shell()->home_view()->backend().printers();
191	    bool has_other_printers = false;
192	    for (const Home::PrinterEntry& entry : saved) {
193	        if (entry.kind != Home::PrinterKind::Named || entry.name == printer.preset_name)
194	            continue;
195	        if (!has_other_printers) {
196	            HeaderMenuItem title;
197	            title.label = _L("OTHER PRINTERS");
198	            title.title = true;
199	            rows.push_back(std::move(title));
200	            has_other_printers = true;
201	        }
202	        HeaderMenuItem other = other_printer(entry);
203	        other.invoke = [self, name = entry.name] {
204	            if (!SetupCommands::select_named_printer(self->m_plater, name))
205	                return; // Orca kept the current printer, including when its prompt was cancelled.
206	            if (ShellController* shell = installed_shell())
207	                shell->status_row()->refresh();
208	        };
209	        rows.push_back(std::move(other));
210	    }
211	    if (has_other_printers)
212	        rows.push_back(separator());
213	
214	    // Printer settings and Add a printer open the printer conversation.
215	    // Settings are about the selected preset, named as Orca keys it: the
216	    // header shows a stock profile's model instead, which names no preset.
217	    // Orca's placeholder is no printer at all, so its settings are adding one.
218	    const bool placeholder = wxGetApp().preset_bundle->printers.get_selected_preset().is_default;
219	    HeaderMenuItem settings;
220	    settings.label  = _L("Printer settings…");
221	    settings.invoke = [preset = placeholder ? std::string() : printer.preset_name] {
222	        if (ShellController* shell = installed_shell())
223	            shell->open_printer_conversation(preset);
224	    };
225	    rows.push_back(std::move(settings));
226	
227	    // A calibration of the first slot's filament on this printer; which test
228	    // is the assistant's question. Board 1 puts it after Printer settings….
229	    HeaderMenuItem calibrate;
230	    calibrate.label   = _L("Calibrate…");
231	    calibrate.enabled = !placeholder && printer.valid;
232	    if (calibrate.enabled) {
233	        const auto slots = SetupCommands::filament_slots();
234	        calibrate.invoke = [name = std::string(printer.nickname.ToUTF8()),
235	                            filament = slots.empty() ? std::string() : std::string(slots.front().filament.alias.ToUTF8())] {
236	            if (ShellController* shell = installed_shell())
237	                shell->start_calibration(name, filament);
238	        };
239	    }
240	    rows.push_back(std::move(calibrate));
241	
242	    HeaderMenuItem add;
243	    add.label  = _L("Add a printer…");
244	    add.invoke = [] {
245	        if (ShellController* shell = installed_shell())
246	            shell->open_printer_conversation();
247	    };
248	    rows.push_back(std::move(add));
249	
250	    menu->replace_items(std::move(rows));
251	}
